// ─── File: src/main/java/com/bank/dashboard/service/TradePaginationService.java ───
package com.bank.dashboard.service;

import com.bank.dashboard.dto.TradePageResponse;
import com.bank.dashboard.model.Trade;
import com.bank.dashboard.repository.TradeRepository;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradePaginationService {

    private final TradeRepository tradeRepo;
    private final EntityManager em;

    // ═══ APPROACH 1: EntityManager low-level ═══
    @Transactional(readOnly = true)
    public TradePageResponse fetchWithEntityManager(int offset, int limit) {
        List<Trade> trades = em.createQuery(
                "SELECT t FROM Trade t WHERE t.status = 'SETTLED' ORDER BY t.amount DESC", Trade.class)
            .setFirstResult(offset)     // OFFSET
            .setMaxResults(limit)       // LIMIT
            .getResultList();

        Long total = em.createQuery("SELECT COUNT(t) FROM Trade t WHERE t.status = 'SETTLED'", Long.class)
            .getSingleResult();

        log.info("[EntityManager] offset={}, limit={}, found={}, total={}", offset, limit, trades.size(), total);

        return new TradePageResponse(
            trades.stream().map(this::format).toList(),
            offset / limit, limit, total, (int) Math.ceil((double) total / limit),
            offset + limit < total, offset > 0,
            "EntityManager setFirstResult/setMaxResults");
    }

    // ═══ APPROACH 2: Spring Data Page (data + count) ═══
    @Transactional(readOnly = true)
    public TradePageResponse fetchWithPage(int page, int size, String sortField, String direction) {
        Sort sort = Sort.by(Sort.Direction.fromString(direction), sortField);
        Pageable pageable = PageRequest.of(page, size, sort);

        Page<Trade> result = tradeRepo.findByStatus("SETTLED", pageable);
        // Fires TWO queries: data + COUNT

        log.info("[Page] page={}, size={}, total={}, pages={}",
            result.getNumber(), result.getSize(), result.getTotalElements(), result.getTotalPages());

        return new TradePageResponse(
            result.getContent().stream().map(this::format).toList(),
            result.getNumber(), result.getSize(),
            result.getTotalElements(), result.getTotalPages(),
            result.hasNext(), result.hasPrevious(),
            "Spring Data Page (data + COUNT query)");
    }

    // ═══ APPROACH 3: Spring Data Slice (no count — infinite scroll) ═══
    @Transactional(readOnly = true)
    public TradePageResponse fetchWithSlice(String accountId, int page, int size) {
        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, "amount"));

        Slice<Trade> slice = tradeRepo.findByAccountId(accountId, pageable);
        // Fires ONE query: SELECT ... LIMIT (size+1) — no COUNT!

        log.info("[Slice] page={}, hasNext={}, content={}", slice.getNumber(), slice.hasNext(), slice.getNumberOfElements());

        return new TradePageResponse(
            slice.getContent().stream().map(this::format).toList(),
            slice.getNumber(), size,
            -1,  // total unknown — no count query!
            -1,  // total pages unknown
            slice.hasNext(), slice.hasPrevious(),
            "Spring Data Slice (NO count — infinite scroll)");
    }

    // ═══ APPROACH 4: Sort only (no pagination) ═══
    @Transactional(readOnly = true)
    public List<String> fetchSorted(String symbol) {
        Sort multiSort = Sort.by(Sort.Order.desc("settlementDate"), Sort.Order.desc("amount"));
        return tradeRepo.findBySymbol(symbol, multiSort).stream()
            .map(this::format).toList();
    }

    private String format(Trade t) {
        return t.getTradeId() + " " + t.getSymbol() + " Rs." + t.getAmount()
            + " [" + t.getStatus() + "] " + t.getSettlementDate();
    }
}
