// ─── File: src/main/java/com/bank/dashboard/controller/TradePageController.java ───
package com.bank.dashboard.controller;

import com.bank.dashboard.dto.TradePageResponse;
import com.bank.dashboard.service.TradePaginationService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/trades")
@RequiredArgsConstructor
public class TradePageController {

    private final TradePaginationService service;

    @GetMapping("/em")
    public TradePageResponse entityManager(
        @RequestParam(defaultValue = "0") int offset,
        @RequestParam(defaultValue = "20") int limit) {
        return service.fetchWithEntityManager(offset, limit);
    }

    @GetMapping("/page")
    public TradePageResponse page(
        @RequestParam(defaultValue = "0") int page,
        @RequestParam(defaultValue = "20") int size,
        @RequestParam(defaultValue = "amount") String sort,
        @RequestParam(defaultValue = "desc") String dir) {
        return service.fetchWithPage(page, size, sort, dir);
    }

    @GetMapping("/slice/{accountId}")
    public TradePageResponse slice(
        @PathVariable String accountId,
        @RequestParam(defaultValue = "0") int page,
        @RequestParam(defaultValue = "20") int size) {
        return service.fetchWithSlice(accountId, page, size);
    }

    @GetMapping("/sorted/{symbol}")
    public List<String> sorted(@PathVariable String symbol) {
        return service.fetchSorted(symbol);
    }
}
