// ─── File: src/test/java/com/bank/dashboard/service/PaginationTest.java ───
package com.bank.dashboard.service;

import org.junit.jupiter.api.Test;
import org.springframework.data.domain.*;
import static org.assertj.core.api.Assertions.*;

class PaginationTest {

    @Test
    void pageRequestCreatesCorrectPageable() {
        Pageable pageable = PageRequest.of(2, 20, Sort.by(Sort.Direction.DESC, "amount"));
        assertThat(pageable.getPageNumber()).isEqualTo(2);
        assertThat(pageable.getPageSize()).isEqualTo(20);
        assertThat(pageable.getOffset()).isEqualTo(40);  // page 2 × size 20 = offset 40
        assertThat(pageable.getSort().getOrderFor("amount").getDirection()).isEqualTo(Sort.Direction.DESC);
    }

    @Test
    void sortComposition() {
        Sort sort = Sort.by(Sort.Order.desc("settlementDate"), Sort.Order.asc("tradeId"));
        assertThat(sort.stream().count()).isEqualTo(2);
        assertThat(sort.getOrderFor("settlementDate").getDirection()).isEqualTo(Sort.Direction.DESC);
        assertThat(sort.getOrderFor("tradeId").getDirection()).isEqualTo(Sort.Direction.ASC);
    }

    @Test
    void pageMetadata() {
        // Simulate Page response
        List<String> content = List.of("T1", "T2", "T3");
        Page<String> page = new PageImpl<>(content, PageRequest.of(2, 3), 100);
        assertThat(page.getContent()).hasSize(3);
        assertThat(page.getTotalElements()).isEqualTo(100);
        assertThat(page.getTotalPages()).isEqualTo(34);  // ceil(100/3)
        assertThat(page.getNumber()).isEqualTo(2);
        assertThat(page.hasNext()).isTrue();
        assertThat(page.hasPrevious()).isTrue();
    }

    @Test
    void sliceHasNoTotalCount() {
        List<String> content = List.of("T1", "T2", "T3");
        Slice<String> slice = new SliceImpl<>(content, PageRequest.of(0, 3), true);
        assertThat(slice.hasNext()).isTrue();
        // slice.getTotalElements() — method doesn't exist on Slice!
        // slice.getTotalPages() — method doesn't exist on Slice!
    }

    @Test
    void offsetCalculation() {
        // page 0, size 20 → offset 0
        // page 1, size 20 → offset 20
        // page 5, size 20 → offset 100
        assertThat(PageRequest.of(0, 20).getOffset()).isEqualTo(0);
        assertThat(PageRequest.of(1, 20).getOffset()).isEqualTo(20);
        assertThat(PageRequest.of(5, 20).getOffset()).isEqualTo(100);
    }
}
